from pathlib import Path

ENGINE = Path("artifacts/api-server/src/lib/execution-engine.ts")
HOME = Path("artifacts/solana-multi-wallet/src/pages/home.tsx")

def replace_once(text, old, new, label):
    if old not in text:
        raise SystemExit(f"Could not patch {label}: expected block not found")
    return text.replace(old, new, 1)

engine = ENGINE.read_text()
engine = replace_once(engine, 'export async function currentSolUsd(): Promise<number> {\n  const headers = jupiterHeaders();\n  if (!headers) {\n    throw new Error("JUPITER_API_KEY is not configured");\n  }\n\n  const response = await fetch(\n    `${jupiterPriceBase}?ids=${encodeURIComponent(solMint)}`,\n    { headers },\n  );\n\n  const payload = await readJson(response);\n\n  if (!response.ok) {\n    throw new Error(\n      stringValue(payload.error) ??\n        `Jupiter SOL/USD price failed (${response.status})`,\n    );\n  }\n\n  const sol = asRecord(payload[solMint]);\n  const usdPrice = numberValue(sol.usdPrice);\n\n  if (usdPrice == null || usdPrice <= 0) {\n    throw new Error("SOL/USD price is unavailable");\n  }\n\n  return usdPrice;\n}\n', 'export async function currentSolUsd(): Promise<number> {\n  const errors: string[] = [];\n\n  const headers = jupiterHeaders();\n\n  if (headers) {\n    try {\n      const response = await fetch(\n        `${jupiterPriceBase}?ids=${encodeURIComponent(solMint)}`,\n        { headers },\n      );\n\n      const payload = await readJson(response);\n\n      if (response.ok) {\n        const sol = asRecord(payload[solMint]);\n        const usdPrice = numberValue(sol.usdPrice);\n\n        if (usdPrice != null && usdPrice > 0) {\n          return usdPrice;\n        }\n      }\n\n      errors.push(\n        stringValue(payload.error) ??\n          `Jupiter ${response.status}`,\n      );\n    } catch (error) {\n      errors.push(\n        error instanceof Error\n          ? `Jupiter: ${error.message}`\n          : "Jupiter failed",\n      );\n    }\n  }\n\n  try {\n    const response = await fetch(\n      "https://api.coingecko.com/api/v3/simple/price?ids=solana&vs_currencies=usd",\n      {\n        headers: {\n          accept: "application/json",\n          "user-agent": "Solana-Multi-Wallet-Panel/1.0",\n        },\n      },\n    );\n\n    const payload = await readJson(response);\n    const solana = asRecord(payload.solana);\n    const usdPrice = numberValue(solana.usd);\n\n    if (response.ok && usdPrice != null && usdPrice > 0) {\n      return usdPrice;\n    }\n\n    errors.push(`CoinGecko ${response.status}`);\n  } catch (error) {\n    errors.push(\n      error instanceof Error\n        ? `CoinGecko: ${error.message}`\n        : "CoinGecko failed",\n    );\n  }\n\n  try {\n    const response = await fetch(\n      "https://api.coinbase.com/v2/prices/SOL-USD/spot",\n      {\n        headers: {\n          accept: "application/json",\n          "user-agent": "Solana-Multi-Wallet-Panel/1.0",\n        },\n      },\n    );\n\n    const payload = await readJson(response);\n    const data = asRecord(payload.data);\n    const usdPrice = numberValue(data.amount);\n\n    if (response.ok && usdPrice != null && usdPrice > 0) {\n      return usdPrice;\n    }\n\n    errors.push(`Coinbase ${response.status}`);\n  } catch (error) {\n    errors.push(\n      error instanceof Error\n        ? `Coinbase: ${error.message}`\n        : "Coinbase failed",\n    );\n  }\n\n  throw new Error(\n    `SOL/USD price is unavailable${errors.length ? ` · ${errors.join(" · ")}` : ""}`,\n  );\n}\n', "SOL/USD fallback providers")
ENGINE.write_text(engine)

home = HOME.read_text()
home = replace_once(home, "  function convertInputAmount(\n    value: string,\n    from: CurrencyMode,\n    to: CurrencyMode,\n  ) {\n    if (from === to || !value) return value;\n\n    const numeric = Number(value);\n    if (!Number.isFinite(numeric) || numeric < 0 || !solUsd) {\n      return value;\n    }\n\n    return to === 'usd'\n      ? trimAmount(numeric * solUsd, 2)\n      : trimAmount(numeric / solUsd, 6);\n  }\n", "  function convertInputAmount(\n    value: string,\n    from: CurrencyMode,\n    to: CurrencyMode,\n    rate = solUsd,\n  ) {\n    if (from === to || !value) return value;\n\n    const numeric = Number(value);\n    if (!Number.isFinite(numeric) || numeric < 0 || !rate) {\n      return value;\n    }\n\n    return to === 'usd'\n      ? trimAmount(numeric * rate, 2)\n      : trimAmount(numeric / rate, 6);\n  }\n", "currency converter")
home = replace_once(home, "  function switchCurrency() {\n    const next: CurrencyMode =\n      currency === 'sol' ? 'usd' : 'sol';\n\n    if (!solUsd) {\n      setNotice(\n        'Live SOL/USD price is unavailable. Try again in a moment.',\n      );\n      return;\n    }\n\n    setBuyAmount((value) =>\n      convertInputAmount(value, currency, next),\n    );\n\n    setTradeDrafts((prev) => {\n      const converted: typeof prev = {};\n\n      for (const [address, draft] of Object.entries(prev)) {\n        converted[address] = {\n          ...draft,\n          buyAmount: convertInputAmount(\n            draft.buyAmount,\n            currency,\n            next,\n          ),\n        };\n      }\n\n      return converted;\n    });\n\n    if (!withdrawMax && withdrawAmount) {\n      setWithdrawAmount((value) =>\n        convertInputAmount(value, currency, next),\n      );\n    }\n\n    setCurrency(next);\n    setNotice('');\n  }\n", "  async function switchCurrency() {\n    const next: CurrencyMode =\n      currency === 'sol' ? 'usd' : 'sol';\n\n    let rate = solUsd;\n\n    if (!rate) {\n      try {\n        const data = await api('/api/execution/sol-usd');\n        const nextRate = Number(data.usdPrice);\n\n        if (Number.isFinite(nextRate) && nextRate > 0) {\n          rate = nextRate;\n          setSolUsd(nextRate);\n        }\n      } catch (error) {\n        setNotice(\n          error instanceof Error\n            ? error.message\n            : 'Live SOL/USD price is unavailable.',\n        );\n        return;\n      }\n    }\n\n    if (!rate) {\n      setNotice('Live SOL/USD price is unavailable.');\n      return;\n    }\n\n    setBuyAmount((value) =>\n      convertInputAmount(value, currency, next, rate),\n    );\n\n    setTradeDrafts((prev) => {\n      const converted: typeof prev = {};\n\n      for (const [address, draft] of Object.entries(prev)) {\n        converted[address] = {\n          ...draft,\n          buyAmount: convertInputAmount(\n            draft.buyAmount,\n            currency,\n            next,\n            rate,\n          ),\n        };\n      }\n\n      return converted;\n    });\n\n    if (!withdrawMax && withdrawAmount) {\n      setWithdrawAmount((value) =>\n        convertInputAmount(value, currency, next, rate),\n      );\n    }\n\n    setCurrency(next);\n    setNotice('');\n  }\n", "currency switch retry")
HOME.write_text(home)

print("v7.2.1 SOL/USD toggle fix applied.")
